+                        <div class="message-item" @onmouseenter="() => hoveredMessageId = msg.Id" @onmouseleave="() => hoveredMessageId = null">
+                            <div class="message-meta">
+                                <span class="message-author">@msg.Author</span>
+                                <span class="message-time">@FormatRelativeTime(msg.SentAt)</span>
+                            </div>
+                            <div class="message-content">@msg.Content</div>
+
+                            @if (msg.Reactions.Count > 0)
+                            {
+                                <div class="reaction-list">
+                                    @foreach (var reaction in msg.Reactions)
+                                    {
+                                        <span class="reaction-badge" title="@string.Join(", ", reaction.Users)">
+                                            @reaction.Emoji @reaction.Users.Count
+                                        </span>
+                                    }
+                                </div>
+                            }
+
+                            @if (threadSummaries.TryGetValue(msg.Id, out var summary))
+                            {
+                                <a class="thread-link" @onclick="() => OpenThreadAsync(msg)" @onclick:preventDefault>
+                                    @summary.ReplyCount replies
+                                </a>
+                            }
+
+                            @if (hoveredMessageId == msg.Id)
+                            {
+                                <div class="message-actions">
+                                    <button class="action-btn" @onclick="() => OpenThreadAsync(msg)" title="Reply in thread">💬 Reply</button>
+                                    <button class="action-btn" @onclick="() => ToggleEmojiPicker(msg.Id)" title="Add reaction">😀 React</button>
+                                </div>
+
+                                @if (emojiPickerMessageId == msg.Id)
+                                {
+                                    <div class="emoji-picker">
+                                        @foreach (var emoji in commonEmojis)
+                                        {
+                                            <button class="emoji-btn" @onclick="() => AddReactionAsync(msg.Id, emoji)">@emoji</button>
+                                        }
+                                    </div>
+                                }
+                            }
+                        </div>
+                    }
+                }
+            </div>
+
+            <div class="message-input-area">
+                <textarea class="message-input" @bind="newMessageContent" @bind:event="oninput"
+                          @onkeydown="OnMessageKeyDownAsync" placeholder="Type a message..." rows="2"></textarea>
+                <button class="send-btn" @onclick="SendMessageAsync" disabled="@string.IsNullOrWhiteSpace(newMessageContent)">Send</button>
+            </div>
+        }
+        else
+        {
+            <div class="no-channel-selected">
+                <p>Select a channel to start chatting</p>
+            </div>
+        }
+    </main>
+
+    @* Right Panel - Thread View *@
+    @if (threadOpen && threadRootMessage is not null)
+    {
+        <aside class="thread-panel">
+            <header class="thread-header">
+                <h3>Thread</h3>
+                <button class="close-thread-btn" @onclick="CloseThread">✕</button>
+            </header>
+
+            <div class="thread-root-message">
+                <div class="message-meta">
+                    <span class="message-author">@threadRootMessage.Author</span>
+                    <span class="message-time">@FormatRelativeTime(threadRootMessage.SentAt)</span>
+                </div>
+                <div class="message-content">@threadRootMessage.Content</div>
+            </div>
+
+            <div class="thread-replies">
+                @if (threadMessages is not null)
+                {
+                    @foreach (var reply in threadMessages)
+                    {
+                        <div class="message-item">
+                            <div class="message-meta">
+                                <span class="message-author">@reply.Author</span>
+                                <span class="message-time">@FormatRelativeTime(reply.SentAt)</span>
+                            </div>
+                            <div class="message-content">@reply.Content</div>
+                        </div>
+                    }
+                }
+            </div>
+
+            <div class="message-input-area">
+                <textarea class="message-input" @bind="threadReplyContent" @bind:event="oninput"
+                          @onkeydown="OnThreadKeyDownAsync" placeholder="Reply in thread..." rows="2"></textarea>
+                <button class="send-btn" @onclick="SendThreadReplyAsync" disabled="@string.IsNullOrWhiteSpace(threadReplyContent)">Reply</button>
+            </div>
+        </aside>
+    }
+</div>
+
+@code {
+    private List<Channel>? channels;
+    private List<Message>? messages;
+    private List<Message>? threadMessages;
+    private Dictionary<int, ThreadSummary> threadSummaries = new();
+
+    private Channel? selectedChannel;
+    private int selectedChannelId;
+    private Message? threadRootMessage;
+    private bool threadOpen;
+
+    private string newMessageContent = string.Empty;
+    private string threadReplyContent = string.Empty;
+
+    private int? hoveredMessageId;
+    private int? emojiPickerMessageId;
+
+    private bool isLoadingMore;
+    private bool hasMoreMessages = true;
+    private const int PageSize = 30;
+
+    private ElementReference messageListRef;
+
+    private static readonly string[] commonEmojis = { "👍", "❤️", "😂", "🎉", "🚀", "👀" };
+
+    protected override async Task OnInitializedAsync()
+    {
+        channels = await ChatService.GetChannelsAsync();
+    }
+
+    private async Task SelectChannelAsync(Channel channel)
+    {
+        selectedChannel = channel;
+        selectedChannelId = channel.Id;
+        messages = null;
+        hasMoreMessages = true;
+        threadSummaries.Clear();
+
+        messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
+        hasMoreMessages = messages.Count >= PageSize;
+
+        await BuildThreadSummariesAsync();
+        await ChatService.MarkChannelReadAsync(channel.Id);
+
+        // Refresh channel list to update unread counts
+        channels = await ChatService.GetChannelsAsync();
+    }
+
+    private async Task BuildThreadSummariesAsync()
+    {
+        if (messages is null) return;
+
+        threadSummaries.Clear();
+
+        // Identify messages that have replies (messages whose ReplyToId points to another message in the list)
+        var rootIds = messages
+            .Where(m => m.ReplyToId.HasValue)
+            .Select(m => m.ReplyToId!.Value)
+            .Distinct()
+            .ToHashSet();
+
+        foreach (var rootId in rootIds)
+        {
+            var replies = messages.Where(m => m.ReplyToId == rootId).ToList();
+            if (replies.Count > 0)
+            {
+                threadSummaries[rootId] = new ThreadSummary(rootId, replies.Count, replies.Max(r => r.SentAt));
+            }
+        }
+    }
+
+    private async Task OnMessageListScrollAsync()
+    {
+        // Scroll-to-top pagination is handled via JS interop
+        if (isLoadingMore || !hasMoreMessages || messages is null) return;
+
+        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('.message-list')?.scrollTop ?? 1");
+        if (scrollTop < 50)
+        {
+            await LoadOlderMessagesAsync();
+        }
+    }
+
+    private async Task LoadOlderMessagesAsync()
+    {
+        if (isLoadingMore || !hasMoreMessages || messages is null) return;
+
+        isLoadingMore = true;
+        StateHasChanged();
+
+        var olderMessages = await ChatService.GetMessagesAsync(selectedChannelId, messages.Count, PageSize);
+        hasMoreMessages = olderMessages.Count >= PageSize;
+
+        if (olderMessages.Count > 0)
+        {
+            messages.InsertRange(0, olderMessages);
+            await BuildThreadSummariesAsync();
+        }
+
+        isLoadingMore = false;
+    }
+
+    private async Task SendMessageAsync()
+    {
+        if (string.IsNullOrWhiteSpace(newMessageContent)) return;
+
+        var sent = await ChatService.SendMessageAsync(selectedChannelId, newMessageContent.Trim(), null);
+        messages ??= new();
+        messages.Add(sent);
+        newMessageContent = string.Empty;
+    }
+
+    private async Task OnMessageKeyDownAsync(KeyboardEventArgs e)
+    {
+        if (e.Key == "Enter" && !e.ShiftKey)
+        {
+            await SendMessageAsync();
+        }
+    }
+
+    private async Task OpenThreadAsync(Message rootMessage)
+    {
+        threadRootMessage = rootMessage;
+        threadOpen = true;
+        emojiPickerMessageId = null;
+
+        threadMessages = await ChatService.GetThreadAsync(rootMessage.Id);
+    }
+
+    private void CloseThread()
+    {
+        threadOpen = false;
+        threadRootMessage = null;
+        threadMessages = null;
+        threadReplyContent = string.Empty;
+    }
+
+    private async Task SendThreadReplyAsync()
+    {
+        if (string.IsNullOrWhiteSpace(threadReplyContent) || threadRootMessage is null) return;
+
+        var reply = await ChatService.SendMessageAsync(selectedChannelId, threadReplyContent.Trim(), threadRootMessage.Id);
+        threadMessages ??= new();
+        threadMessages.Add(reply);
+        threadReplyContent = string.Empty;
+
+        // Update thread summary in main view
+        messages?.Add(reply);
+        await BuildThreadSummariesAsync();
+    }
+
+    private async Task OnThreadKeyDownAsync(KeyboardEventArgs e)
+    {
+        if (e.Key == "Enter" && !e.ShiftKey)
+        {
+            await SendThreadReplyAsync();
+        }
+    }
+
+    private void ToggleEmojiPicker(int messageId)
+    {
+        emojiPickerMessageId = emojiPickerMessageId == messageId ? null : messageId;
+    }
+
+    private async Task AddReactionAsync(int messageId, string emoji)
+    {
+        await ChatService.AddReactionAsync(messageId, emoji);
+        emojiPickerMessageId = null;
+
+        // Refresh messages to show updated reactions
+        if (messages is not null)
+        {
+            messages = await ChatService.GetMessagesAsync(selectedChannelId, 0, messages.Count);
+            await BuildThreadSummariesAsync();
+        }
+    }
+
+    private static string FormatRelativeTime(DateTime sentAt)
+    {
+        var diff = DateTime.UtcNow - sentAt;
+
+        if (diff.TotalSeconds < 60) return "just now";
+        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
+        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
+        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
+        return sentAt.ToString("MMM d, yyyy");
+    }
+
+    private static string TruncateDescription(string description)
+    {
+        return description.Length > 40 ? description[..37] + "..." : description;
+    }
+}
+

toolArgs.file_text:
.chat-container {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* Sidebar */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #1a1d21;
    color: #ccc;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #333;
    overflow-y: auto;
}

.sidebar-title {
    padding: 16px 16px 8px;
    font-size: 1rem;
    font-weight: 700;
    color: #fff;
    margin: 0;
}

.channel-list {
    list-style: none;
    padding: 0;
    margin: 0;
}

.channel-item {
    padding: 10px 16px;
    cursor: pointer;
    position: relative;
    border-left: 3px solid transparent;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #26292e;
}

.channel-item.active {
    background: #1164a3;
    border-left-color: #fff;
    color: #fff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.9rem;
}

.channel-description {
    font-size: 0.75rem;
    color: #999;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.channel-item.active .channel-description {
    color: #ddd;
}

.unread-badge {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: #e01e5a;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* Main Message Area */
.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #fff;
    min-width: 0;
}

.message-area.thread-open {
    max-width: 55%;
}

.message-header {
    padding: 12px 20px;
    border-bottom: 1px solid #e8e8e8;
    flex-shrink: 0;
}

.message-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #1d1c1d;
}

.message-header p {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #616061;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
}

.loading-indicator {
    text-align: center;
    padding: 8px;
    color: #888;
    font-size: 0.8rem;
}

.message-item {
    padding: 8px 12px;
    margin-bottom: 4px;
    border-radius: 6px;
    position: relative;
    transition: background 0.1s;
}

.message-item:hover {
    background: #f8f8f8;
}

.message-meta {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.message-author {
    font-weight: 700;
    font-size: 0.9rem;
    color: #1d1c1d;
}

.message-time {
    font-size: 0.75rem;
    color: #616061;
}

.message-content {
    font-size: 0.9rem;
    color: #1d1c1d;
    line-height: 1.4;
    word-wrap: break-word;
}

.reaction-list {
    display: flex;
    gap: 4px;
    margin-top: 6px;
    flex-wrap: wrap;
}

.reaction-badge {
    background: #f0f4ff;
    border: 1px solid #d0d8e8;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: default;
    user-select: none;
}

.thread-link {
    display: inline-block;
    margin-top: 4px;
    font-size: 0.8rem;
    color: #1264a3;
    cursor: pointer;
    text-decoration: none;
    font-weight: 600;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: 4px;
    right: 8px;
    display: flex;
    gap: 4px;
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 2px 4px;
    box-shadow: 0 1px 4px rgba(0,0,0,0.1);
}

.action-btn {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 0.75rem;
    padding: 4px 8px;
    border-radius: 4px;
    color: #555;
}

.action-btn:hover {
    background: #f0f0f0;
}

.emoji-picker {
    position: absolute;
    top: -40px;
    right: 8px;
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 6px;
    display: flex;
    gap: 4px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.15);
    z-index: 10;
}

.emoji-btn {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px;
    border-radius: 4px;
    line-height: 1;
}

.emoji-btn:hover {
    background: #f0f0f0;
}

/* Message Input */
.message-input-area {
    display: flex;
    gap: 8px;
    padding: 12px 20px;
    border-top: 1px solid #e8e8e8;
    flex-shrink: 0;
    align-items: flex-end;
}

.message-input {
    flex: 1;
    resize: none;
    border: 1px solid #ccc;
    border-radius: 8px;
    padding: 10px 12px;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
    transition: border-color 0.15s;
}

.message-input:focus {
    border-color: #1264a3;
}

.send-btn {
    background: #007a5a;
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 10px 20px;
    font-size: 0.85rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
}

.send-btn:hover:not(:disabled) {
    background: #005e44;
}

.send-btn:disabled {
    background: #ccc;
    cursor: not-allowed;
}

/* No Channel Selected */
.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 1;
    color: #888;
    font-size: 1.1rem;
}

/* Thread Panel */
.thread-panel {
    width: 25%;
    min-width: 280px;
    border-left: 1px solid #e8e8e8;
    background: #fff;
    display: flex;
    flex-direction: column;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #e8e8e8;
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
}

.close-thread-btn {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    color: #666;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-thread-btn:hover {
    background: #f0f0f0;
}

.thread-root-message {
    padding: 12px 16px;
    background: #f8f8f8;
    border-bottom: 1px solid #e8e8e8;
    flex-shrink: 0;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
}

.thread-panel .message-input-area {
    padding: 12px 16px;
}

